<script lang="ts">
 import {ChartNoAxesCombined} from 'lucide-svelte';import Protected from '@lib/components/Protected.svelte';import Metrics from '@lib/components/Metrics.svelte';import Activity from '@lib/components/Activity.svelte';import {api} from '@lib/api';import {user} from '@lib/session';import type {Summary} from '@lib/types';
 let days=$state(30),summary=$state<Summary|null>(null),activity=$state<{date:string;count:number}[]>([]),objects=$state<{label:string;count:number}[]>([]),sources=$state<{label:string;count:number}[]>([]),error=$state(''),loading=$state(false),revision=0;
 async function load(){const rev=++revision;loading=true;error='';try{const result=await Promise.all(['summary','activity','objects','sources'].map(p=>api(`/analytics/${p}?days=${days}`)));if(rev===revision)[summary,activity,objects,sources]=result as any;}catch(e){if(rev===revision)error=(e as Error).message;}finally{if(rev===revision)loading=false;}}
 $effect(()=>{if($user)load();});
</script>
<Protected><div class="page-title"><div><h1>Analytics</h1><p>The patterns behind your perspective. Based on saved snapshots.</p></div><select aria-label="Analytics period" bind:value={days} onchange={load}><option value={7}>Last 7 days</option><option value={30}>Last 30 days</option><option value={90}>Last 90 days</option><option value={0}>All time</option></select></div>{#if error}<div class="notice error">{error}<button onclick={load}>Retry</button></div>{:else if loading}<div class="loading-state">Calculating your analytics…</div>{:else if summary}<Metrics data={summary} analytics/><section class="panel"><div class="panel-heading"><h2>Detection activity</h2><span>Saved snapshots · UTC</span></div><Activity data={activity} {days}/></section><div class="analytics-grid"><section class="panel"><div class="panel-heading"><h2>Top detected objects</h2><span>{objects.length} categories</span></div><div class="panel-content">{#each objects.slice(0,8) as o}<div class="bar-row"><div><span>{o.label}</span><strong>{o.count}</strong></div><div class="bar-track"><span style={`width:${o.count/(objects[0]?.count||1)*100}%`}></span></div></div>{:else}<p class="inline-empty">Your most detected categories will appear here.</p>{/each}</div></section><section class="panel"><div class="panel-heading"><h2>Category distribution</h2></div><div class="panel-content">{#each objects as o}<div class="prediction"><span>{o.label}</span><strong>{(o.count/summary.total_objects*100).toFixed(1)}% <small>· {o.count}</small></strong></div>{:else}<p class="inline-empty">Save a detection to discover your category mix.</p>{/each}</div></section><section class="panel"><div class="panel-heading"><h2>Detection sources</h2></div><div class="panel-content">{#each ['camera','image'] as s}{@const count=sources.find(o=>o.label===s)?.count||0}<div class="bar-row"><div><span>{s==='camera'?'Live camera':'Image upload'}</span><strong>{count}</strong></div><div class="bar-track"><span style={`width:${summary.total_detections?count/summary.total_detections*100:0}%`}></span></div></div>{/each}<p class="field-help">Only explicitly saved snapshots count toward analytics.</p></div></section></div>{/if}</Protected>
